  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "A young woman sent by Wednesday to fetch water for linen goes instead to a neighbor before dawn.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "An aged woman warns that Wednesday means to harm the young woman in connection with the linen.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "The aged woman instructs her to beat the pails, cry that Wednesday's children have been burnt at sea, then protect the door with crosses and prayer.",
      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "Wednesday runs out at the false cry, and the young woman gets inside, shuts the door, and marks it with a cross.",
      "category": "sequence",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "Wednesday knocks and pleads until cockcrow, then gives a shrill cry and disappears, while the linen remains behind.",
      "category": "sequence",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:6",
      "text": "St. Petka or Friday and St. Nedelya or Sunday are named among revered saints, and Sunday is said to correspond to Greek St. Anastasia and German Holy Sunday.",
      "category": "relationship",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:7",
      "text": "Sunday shares Friday's and Wednesday's concern about spinning or weaving at improper times, and in Little-Russia she says untimely spinners are spinning her hair.",
      "category": "attribute",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:8",
      "text": "In Wallachian tales, Mothers Friday, Wednesday, and Sunday help a hero search for a dragon-stolen heroine and help another seeker look for a lost husband.",
      "category": "action",
      "evidence_refs": [
        "ev:7",
        "ev:8"
      ]
    },
    {
      "id": "obs:9",
      "text": "Mother Sunday is said to rule animals, summon birds and beasts with a magic flute, and in a Slovak story provide magical implements and a horse.",
      "category": "attribute",
      "evidence_refs": [
        "ev:8",
        "ev:9"
      ]
    },
    {
      "id": "obs:10",
      "text": "In the Slovak story, a dragon-corrupted mother and the dragon cause the youth to be killed and cut to pieces, after which St. Nedelka reanimates him.",
      "category": "sequence",
      "evidence_refs": [
        "ev:9",
        "ev:10"
      ]
    },
    {
      "id": "obs:11",
      "text": "The youth's separated heart is later recovered and restored to him by the magic bird Pelekan.",
      "category": "sequence",
      "evidence_refs": [
        "ev:11"
      ]
    },
    {
